function passwordPage(){const token=supabase.adoptHashSession();return `<div class="login-page"><section class="login-brand"><div><img src="${APP_CONFIG.logoPath}"><h1>Defina uma senha segura.</h1><p>Esse acesso será usado para entrar no painel do TAJO Avalie.</p></div></section><section class="login-side"><form class="login-box" id="password-form"><h2>Nova senha</h2><p>${token?'Seu link foi validado. Escolha sua nova senha.':'Abra novamente o link enviado pelo Supabase para validar seu acesso.'}</p><div class="field"><label>Nova senha</label><input name="password" type="password" minlength="8" required ${token?'':'disabled'}></div><div class="field"><label>Confirmar senha</label><input name="confirm" type="password" minlength="8" required ${token?'':'disabled'}></div><button class="btn btn-primary btn-block" ${token?'':'disabled'}>Salvar nova senha</button></form></section></div>`}

async function publicPage(companySlug,pointSlug){
  const key=`${companySlug}/${pointSlug}`
  if(state.public.key!==key)state.public={key,step:1,rating:null,reasons:[],comment:'',ctx:null}
  try { if(!state.public.ctx) state.public.ctx=await api.publicContext(companySlug,pointSlug) }
  catch(err){ return `<div class="public-premium"><section class="public-experience"><img class="public-logo" src="${APP_CONFIG.logoPath}" alt="Supermercado Schwambach"><div class="public-error"><span class="premium-kicker">LINK TEMPORARIAMENTE INDISPONÍVEL</span><h2>Não foi possível abrir a avaliação.</h2><p>${esc(err.message||'Verifique a configuração do banco e tente novamente.')}</p><button class="btn btn-primary" data-retry>Tentar novamente</button></div><small>SUPERMERCADO SCHWAMBACH</small></section></div>` }
  const c=state.public.ctx.company,p=state.public.ctx.point,reasons=state.public.ctx.reasons||[]
  const current=state.public.step
  const progress=`<div class="public-progress"><span>ETAPA ${Math.min(current,3).toString().padStart(2,'0')} / 03</span><div class="public-track"><i style="width:${current===4?100:(current/3)*100}%"></i></div><span>${current===4?'CONCLUÍDO':current===1?'SUA EXPERIÊNCIA':current===2?'DETALHES':'FINALIZAR'}</span></div>`
  let content=''
  if(current===1)content=`<div class="public-prompt"><span class="public-step">01 / AVALIE O ATENDIMENTO</span><h1>${esc(c.feedback_question||'Como foi seu atendimento?')}</h1><p>${esc(c.feedback_subtitle||'Sua opinião é muito importante para nós.')}</p></div><div class="premium-ratings" role="group" aria-label="Nota de 1 a 5"><div class="premium-ratings-caption">SELECIONE UMA NOTA</div><div class="premium-ratings-row">${[1,2,3,4,5].map(n=>`<button type="button" class="premium-rating ${state.public.rating===n?'selected':''}" data-rating="${n}" aria-label="${n} de 5 — ${ratingLabel(n)}" aria-pressed="${state.public.rating===n}"><span class="rating-emoji">${ratingEmoji(n)}</span><b>${n}</b><small>${ratingLabel(n)}</small></button>`).join('')}</div><div class="ratings-help">Ao selecionar a nota, você avança automaticamente.</div></div>`
  if(current===2)content=`<div class="public-prompt"><span class="public-step">02 / DETALHES DA EXPERIÊNCIA</span><h1>O que mais influenciou sua avaliação?</h1><p>Selecione as opções que melhor representam seu atendimento. Você pode escolher mais de uma.</p></div><div class="premium-reasons">${reasons.map(r=>`<button type="button" class="premium-reason ${state.public.reasons.includes(r.code)?'selected':''}" data-reason="${esc(r.code)}" aria-pressed="${state.public.reasons.includes(r.code)}"><span class="reason-check">${state.public.reasons.includes(r.code)?'✓':'+'}</span>${esc(r.label)}</button>`).join('')}</div><div class="public-controls"><button type="button" class="btn btn-outline" data-public-back>← Voltar</button><button type="button" class="btn btn-primary" data-public-next>Continuar <span aria-hidden="true">→</span></button></div>`
  if(current===3)content=`<div class="public-prompt"><span class="public-step">03 / ÚLTIMA ETAPA</span><h1>Gostaria de deixar um comentário?</h1><p>Este campo é opcional. Conte-nos um detalhe que possa ajudar nossa equipe.</p></div>${c.comments_enabled!==false?`<div class="field premium-comment"><label for="public-comment">SEU COMENTÁRIO <span>OPCIONAL</span></label><textarea id="public-comment" maxlength="500" placeholder="Escreva aqui, se desejar…">${esc(state.public.comment)}</textarea><small>Até 500 caracteres • Não informe dados pessoais</small></div>`:''}<div class="privacy-note">◈ Sua avaliação não exige nome, telefone ou CPF.</div><div class="public-controls"><button type="button" class="btn btn-outline" data-public-back>← Voltar</button><button type="button" class="btn btn-primary" data-submit-feedback>Enviar avaliação <span aria-hidden="true">→</span></button></div>`
  if(current===4)content=`<div class="premium-thanks"><div class="thanks-emblem">✓</div><span class="public-step">AVALIAÇÃO REGISTRADA</span><h1>Obrigado por compartilhar.</h1><p>${esc(c.thank_you_message||'Sua opinião nos ajuda a melhorar.')}</p><div class="thanks-footer">Sua participação faz a diferença para nossa equipe.</div><button type="button" class="btn btn-outline" data-public-reset>Encerrar</button></div>`
  return `<div class="public-premium"><div class="public-experience"><aside class="experience-side"><a href="/" data-link class="experience-logo"><img src="${APP_CONFIG.logoPath}" alt="Logo Supermercado Schwambach"></a><div class="experience-side-middle"><span class="premium-kicker"><i></i> SUA VOZ TEM VALOR</span><h2>Cada experiência nos ajuda a ser melhores.</h2><p>Levamos a sério o que você tem a dizer. Obrigado por fazer parte da nossa evolução.</p><div class="experience-point"><span>VOCÊ ESTÁ AVALIANDO</span><b>${esc(p.name)}</b><small>Supermercado Schwambach</small></div></div><div class="experience-side-bottom"><span>ESCUTAR. ENTENDER. EVOLUIR.</span><span>EST. SCHWAMBACH</span></div></aside><main class="experience-main"><div class="experience-mobile-brand"><img src="${APP_CONFIG.logoPath}" alt="Supermercado Schwambach"><div><b>Schwambach</b><span>${esc(p.name)}</span></div></div>${progress}<div class="experience-form">${content}</div><footer class="experience-foot"><span>SUPERMERCADO SCHWAMBACH</span><span>Tecnologia TAJO Digital</span></footer></main></div></div>`
}

function dashboardPage(d){
  const sum=d.dashboard||{},open=d.incidents.filter(i=>!['resolved','archived'].includes(i.status)).slice(0,4),best=d.topEmployees?.slice(0,4)||[]
  return shell(d,'dashboard',`${pageHead('Visão geral',`Indicadores reais dos últimos 30 dias · atualizado às ${new Date(d.loadedAt||Date.now()).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}`,`<button class="btn btn-outline" data-refresh>Atualizar dados</button><button class="btn btn-primary" data-new-point>+ Novo ponto</button>`)}<div class="stats">${stat('Nota média',Number(sum.average_rating||0).toFixed(2),'Últimos 30 dias','★','green')}${stat('Avaliações',String(sum.evaluations||0),'Volume do período','▤')}${stat('Positivas',pct(sum.positive_percent),'Notas 4 e 5','✓','green')}${stat('Alertas ativos',String(sum.open_incidents||0),'Requer acompanhamento','!','red')}</div><div class="grid-2"><section class="panel"><header class="panel-head"><div><h2>Evolução da satisfação</h2><p>Leitura rápida da nota média</p></div>${badge(d.historySource==='recentes'?'Amostra recente':'Últimos 30 dias','blue')}</header><div class="panel-body">${lineChart(d.history)}</div></section><section class="panel"><header class="panel-head"><div><h2>Precisa da sua atenção</h2><p>Ocorrências abertas</p></div><button class="btn btn-outline btn-sm" data-nav="ocorrencias">Ver todas</button></header><div class="panel-body"><div class="attention">${open.length?open.map(i=>`<div class="attention-item"><span class="attention-dot ${i.severity}"></span><div><b>${esc(i.title)}</b><small>${esc(i.point_name||'Operação geral')} • ${ago(i.created_at)}</small></div><button class="btn btn-outline btn-sm" data-open-incident="${i.id}">Abrir</button></div>`).join(''):empty('Nenhum alerta ativo','A operação está sem ocorrências abertas.')}</div></div></section></div><div class="grid-2" style="margin-top:14px"><section class="panel"><header class="panel-head"><div><h2>Motivos mais citados</h2><p>O que mais aparece nas avaliações</p></div></header><div class="panel-body"><div class="metric-bars">${(d.reasons||[]).slice(0,6).map((r,i,a)=>`<div class="metric-row"><span>${esc(r.reason_label||r.label)}</span><div class="bar"><i style="width:${clamp(Number(r.mention_count||r.value||0)/Math.max(1,Number(a[0]?.mention_count||a[0]?.value||1))*100,3,100)}%"></i></div><b>${Number(r.mention_count||r.value||0)}</b></div>`).join('')}</div></div></section><section class="panel"><header class="panel-head"><div><h2>Destaques do atendimento</h2><p>Ranking pelo período</p></div></header><div class="panel-body"><div class="attention">${best.length?best.map((e,i)=>`<div class="attention-item"><span style="font-weight:900;color:${i===0?'#d89a09':'#5f6d84'}">${i+1}º</span><div><b>${esc(e.employee_name)}</b><small>${Number(e.review_count)} avaliações • ${pct(e.positive_percent)} positivas</small></div><b class="score">★ ${Number(e.average_rating).toFixed(2)}</b></div>`).join(''):empty('Ranking ainda sem dados')}</div></div></section></div><section class="panel" style="margin-top:14px"><header class="panel-head"><div><h2>Desempenho dos pontos</h2><p>Caixas e setores monitorados</p></div><button class="btn btn-outline btn-sm" data-nav="pontos">Gerenciar pontos</button></header><div class="table-wrap"><table class="table"><thead><tr><th>Ponto</th><th>Funcionário atual</th><th>Nota</th><th>Avaliações</th><th>Status</th><th></th></tr></thead><tbody>${d.points.slice(0,8).map(p=>{const m=pointMetric(d,p);return `<tr><td><strong>${esc(p.name)}</strong><br><span class="muted">${esc(p.point_type)}</span></td><td>${esc(p.employee_name||'Sem turno ativo')}</td><td><span class="score">★ ${m.score?m.score.toFixed(2):'—'}</span></td><td>${m.reviews}</td><td>${m.score&&m.score<3.8?badge('Atenção','red'):badge('Operando','green')}</td><td><button class="btn btn-outline btn-sm" data-point-detail="${p.id}">Abrir</button></td></tr>`}).join('')}</tbody></table></div></section>`,{})
}

function evaluationsPage(d){const f=d.feedbacks||[];return shell(d,'avaliacoes',`${pageHead('Avaliações','Acompanhe as 250 avaliações mais recentes, filtre as notas e exporte o histórico completo.',`<button class="btn btn-outline" data-export-feedback>Exportar CSV</button>`)}<div class="toolbar"><input id="feedback-search" placeholder="Pesquisar comentário, caixa ou funcionário…"><select id="feedback-rating"><option value="">Todas as notas</option>${[5,4,3,2,1].map(n=>`<option value="${n}">${n} • ${ratingLabel(n)}</option>`).join('')}</select><select id="feedback-status"><option value="">Todos os status</option><option value="new">Nova</option><option value="analyzing">Em análise</option><option value="resolved">Resolvida</option><option value="archived">Arquivada</option></select></div><div class="cards" id="feedback-list">${f.length?f.map(x=>`<article class="review" data-feedback-card data-rating="${x.rating}" data-status="${x.status}"><div class="review-score">${ratingEmoji(x.rating)}<small>${x.rating}/5</small></div><div><h3>${esc(x.point_name||point(d,x.point_id)?.name||'Ponto')} • ${esc(x.employee_name||'Sem funcionário')}</h3><div class="tags">${(x.reason_codes||[]).map(r=>badge(reasonLabel(r),x.rating<=2?'red':'blue')).join('')}</div><p>${x.comment?`“${esc(x.comment)}”`:'<span class="muted">Sem comentário.</span>'}</p><footer>${dt(x.created_at)} • ${ratingLabel(x.rating)}</footer></div><div>${statusBadge(x.status)}<div style="height:8px"></div><button class="btn btn-outline btn-sm" data-feedback-detail="${x.id}">Abrir</button></div></article>`).join(''):empty('Nenhuma avaliação ainda','As novas avaliações aparecerão aqui.')}</div>`,{})}

function pointsPage(d){const used=d.points.filter(p=>p.active).length,limit=d.subscription?.point_limit||d.company.point_limit||12;return shell(d,'pontos',`${pageHead('Pontos / Caixas','Cada ponto possui um link permanente para avaliação.',`<button class="btn btn-primary" data-new-point>+ Novo ponto</button>`)}<div class="usage"><div class="usage-top"><b>Pontos utilizados</b><span>${used} de ${limit}</span></div><div class="usage-bar"><i style="width:${clamp(used/limit*100,0,100)}%"></i></div></div><div class="point-grid">${d.points.map(p=>{const m=pointMetric(d,p);return `<article class="point-card"><div class="card-title"><h3>${esc(p.name)}</h3>${p.active?badge('Ativo','green'):badge('Inativo')}</div><div class="card-kv"><div class="kv"><span>Tipo</span><b>${esc(p.point_type)}</b></div><div class="kv"><span>Nota</span><b>${m.score?`★ ${m.score.toFixed(2)}`:'—'}</b></div><div class="kv"><span>Funcionário</span><b>${esc(p.employee_name||'Sem turno')}</b></div><div class="kv"><span>Avaliações</span><b>${m.reviews}</b></div></div><div class="card-actions"><button class="btn btn-outline btn-sm" data-point-detail="${p.id}">Detalhes</button><button class="btn btn-outline btn-sm" data-edit-point="${p.id}">Editar</button><button class="btn btn-outline btn-sm" data-point-qr="${p.id}">QR / Link</button><a class="btn btn-outline btn-sm" target="_blank" href="/${d.company.slug}/${p.slug}">Avaliar</a></div></article>`}).join('')}</div>`,{})}

function employeesPage(d){return shell(d,'funcionarios',`${pageHead('Funcionários','Cadastre a equipe e acompanhe o desempenho associado aos turnos.',`<button class="btn btn-primary" data-new-employee>+ Novo funcionário</button>`)}<div class="employee-grid">${d.employees.map(e=>{const m=employeeMetric(d,e),p=d.points.find(p=>p.employee_id===e.id);return `<article class="employee-card"><div class="card-title"><div style="display:flex;align-items:center;gap:9px"><span class="avatar">${initials(e.name)}</span><div><h3>${esc(e.name)}</h3><span class="muted" style="font-size:9px">${esc(e.role_name||'Equipe')}</span></div></div>${e.active?badge('Ativo','green'):badge('Inativo')}</div><div class="card-kv"><div class="kv"><span>Nota</span><b>${m.score?`★ ${m.score.toFixed(2)}`:'—'}</b></div><div class="kv"><span>Avaliações</span><b>${m.reviews}</b></div><div class="kv"><span>Ponto atual</span><b>${esc(p?.name||'—')}</b></div><div class="kv"><span>Código</span><b>${esc(e.employee_code||'—')}</b></div></div><div class="card-actions"><button class="btn btn-outline btn-sm" data-edit-employee="${e.id}">Editar funcionário</button></div></article>`}).join('')}</div>`,{})}

function shiftsPage(d){const active=d.shifts.filter(s=>s.status==='active');return shell(d,'turnos',`${pageHead('Turnos','Associe o funcionário ao ponto sem nunca precisar trocar o QR Code.',`<button class="btn btn-primary" data-new-shift>+ Iniciar turno</button>`)}<section class="panel"><header class="panel-head"><div><h2>Operação atual</h2><p>${active.length} turnos ativos agora</p></div></header><div class="table-wrap"><table class="table"><thead><tr><th>Ponto</th><th>Funcionário</th><th>Início</th><th>Status</th><th></th></tr></thead><tbody>${active.length?active.map(s=>`<tr><td><strong>${esc(point(d,s.point_id)?.name||'Ponto')}</strong></td><td>${esc(employee(d,s.employee_id)?.name||'Funcionário')}</td><td>${dt(s.started_at)}</td><td>${badge('Em operação','green')}</td><td><button class="btn btn-outline btn-sm" data-end-shift="${s.id}">Encerrar</button></td></tr>`).join(''):`<tr><td colspan="5">${empty('Nenhum turno ativo')}</td></tr>`}</tbody></table></div></section><section class="panel"><header class="panel-head"><div><h2>Histórico recente</h2><p>Últimos turnos registrados</p></div></header><div class="table-wrap"><table class="table"><thead><tr><th>Ponto</th><th>Funcionário</th><th>Início</th><th>Fim</th></tr></thead><tbody>${d.shifts.filter(s=>s.status!=='active').slice(0,30).map(s=>`<tr><td>${esc(point(d,s.point_id)?.name||'Ponto')}</td><td>${esc(employee(d,s.employee_id)?.name||'Funcionário')}</td><td>${dt(s.started_at)}</td><td>${dt(s.ended_at)}</td></tr>`).join('')}</tbody></table></div></section>`,{})}

function incidentsPage(d){return shell(d,'ocorrencias',`${pageHead('Ocorrências','Transforme avaliações críticas em acompanhamento operacional.') }<div class="stats">${stat('Novas',d.incidents.filter(i=>i.status==='new').length,'Ainda não analisadas','!','red')}${stat('Em análise',d.incidents.filter(i=>i.status==='analyzing').length,'Em acompanhamento','◷','amber')}${stat('Resolvidas',d.incidents.filter(i=>i.status==='resolved').length,'Histórico tratado','✓','green')}${stat('Críticas',d.incidents.filter(i=>i.severity==='critical'&&!['resolved','archived'].includes(i.status)).length,'Prioridade alta','⚠','red')}</div><div class="cards">${d.incidents.map(i=>`<article class="review"><div class="review-score">${i.severity==='critical'?'🚨':i.severity==='warning'?'⚠️':'ℹ️'}</div><div><h3>${esc(i.title)}</h3><div class="tags">${badge(i.severity==='critical'?'Crítica':i.severity==='warning'?'Atenção':'Informativa',i.severity==='critical'?'red':i.severity==='warning'?'amber':'blue')}${statusBadge(i.status)}</div><p>${esc(i.description||'')}</p><footer>${esc(i.point_name||'Operação geral')} • ${dt(i.created_at)}</footer></div><div><button class="btn btn-outline btn-sm" data-open-incident="${i.id}">Gerenciar</button></div></article>`).join('')}</div>`,{})}

function rankingPage(d){const arr=(d.topEmployees||[]).sort((a,b)=>Number(b.average_rating)-Number(a.average_rating));return shell(d,'ranking',`${pageHead('Ranking de atendimento','Reconheça quem entrega a melhor experiência, sem transformar o sistema em ferramenta punitiva.')}<section class="panel"><header class="panel-head"><div><h2>Destaques do período</h2><p>Considera avaliações vinculadas aos turnos</p></div>${badge('Mínimo configurável','blue')}</header><div class="table-wrap"><table class="table"><thead><tr><th>Posição</th><th>Funcionário</th><th>Nota média</th><th>Avaliações</th><th>Positivas</th></tr></thead><tbody>${arr.map((e,i)=>`<tr><td><strong>${i===0?'🥇':i===1?'🥈':i===2?'🥉':`${i+1}º`}</strong></td><td><strong>${esc(e.employee_name)}</strong></td><td><span class="score">★ ${Number(e.average_rating).toFixed(2)}</span></td><td>${e.review_count}</td><td>${pct(e.positive_percent)}</td></tr>`).join('')}</tbody></table></div></section>`,{})}

function reportsPage(d){return shell(d,'relatorios',`${pageHead('Relatórios','Encontre padrões de atendimento, horários críticos e motivos recorrentes.',`<button class="btn btn-outline" data-export-feedback>Exportar avaliações</button>`)}<div class="grid-2"><section class="panel"><header class="panel-head"><div><h2>Horários críticos</h2><p>Nota média por faixa de horário</p></div></header><div class="panel-body"><div class="metric-bars">${(d.hourly||[]).map(h=>`<div class="metric-row"><span>${String(h.hour_of_day).padStart(2,'0')}h</span><div class="bar"><i style="width:${Number(h.average_rating)/5*100}%;${Number(h.average_rating)<4?'background:linear-gradient(90deg,#ef2533,#ff7a42)':''}"></i></div><b>${Number(h.average_rating).toFixed(1)}</b></div>`).join('')}</div></div></section><section class="panel"><header class="panel-head"><div><h2>Motivos recorrentes</h2><p>Quantidade de menções</p></div></header><div class="panel-body"><div class="metric-bars">${(d.reasons||[]).map((r,i,a)=>`<div class="metric-row"><span>${esc(r.reason_label)}</span><div class="bar"><i style="width:${Number(r.mention_count)/Math.max(1,Number(a[0]?.mention_count||1))*100}%"></i></div><b>${r.mention_count}</b></div>`).join('')}</div></div></section></div><section class="panel" style="margin-top:14px"><header class="panel-head"><div><h2>Desempenho por ponto</h2><p>Compare caixas e setores</p></div></header><div class="table-wrap"><table class="table"><thead><tr><th>Ponto</th><th>Tipo</th><th>Média</th><th>Avaliações</th><th>Negativas</th></tr></thead><tbody>${(d.pointPerformance||[]).map(p=>`<tr><td><strong>${esc(p.point_name)}</strong></td><td>${esc(p.point_type)}</td><td><span class="score">★ ${Number(p.average_rating).toFixed(2)}</span></td><td>${p.review_count}</td><td>${p.negative_count}</td></tr>`).join('')}</tbody></table></div></section>`,{})}

function qrPage(d){
 const all=d.points.filter(p=>p.active).sort((a,b)=>a.slug.localeCompare(b.slug,'pt-BR'))
 const cards=all.map(p=>{const n=p.slug,known=/^caixa-(0[1-9]|1[0-2])$/.test(n),u=publicUrl(d.company.slug,n),image=known?`/qrcodes/${n}.svg`:`https://quickchart.io/qr?text=${encodeURIComponent(u)}&size=320&margin=4`;
 return `<article class="premium-qr-card"><div class="qr-card-top"><div><span class="qr-overline">PONTO DE ATENDIMENTO</span><h3>${esc(p.name)}</h3></div>${badge('ATIVO','green')}</div><div class="premium-qr-frame"><img src="${image}" alt="QR Code para ${esc(p.name)}" width="208" height="208" loading="lazy"></div><p class="qr-card-caption">Aponte a câmera para avaliar este caixa.</p><div class="qr-link-text">${esc(u)}</div><div class="qr-card-actions"><button type="button" class="btn btn-outline btn-sm" data-copy="${esc(u)}">Copiar link</button><a class="btn btn-outline btn-sm" target="_blank" rel="noopener" href="${previewUrl(d.company.slug,n)}">Abrir</a>${known?`<a class="btn btn-primary btn-sm" href="/qrcodes/${n}.png" download="schwambach-${n}.png">Baixar QR</a><a class="btn btn-outline btn-sm" href="/placas/${n}.html" target="_blank" rel="noopener">Imprimir</a>`:`<a class="btn btn-primary btn-sm" href="${image}" target="_blank" rel="noopener">Gerar QR</a>`}</div></article>`}).join('')
 return shell(d,'qrcodes',`${pageHead('QR Codes dos caixas','Arquivos individuais, prontos para impressão e colocação nos caixas.',`<button class="btn btn-outline" data-print-page>Imprimir relação</button>`)}<section class="qr-intro"><div><span class="premium-kicker"><i></i> IDENTIDADE EXCLUSIVA SCHWAMBACH</span><h2>12 pontos. 12 acessos independentes.</h2><p>O QR permanece no caixa mesmo quando o operador muda. O vínculo com o funcionário é feito pelo turno, no painel de gestão.</p></div><div class="qr-domain"><small>DOMÍNIO OFICIAL</small><strong>avaliesch.tajodigital.com.br</strong><span>Links canônicos para impressão</span></div></section><div class="premium-qr-grid">${cards}</div>`,{})
}

function teamPage(d){return shell(d,'equipe',`${pageHead('Equipe e acessos','Proprietários e gerentes possuem login individual e permissões separadas.',d.currentUser?.role==='owner'?`<button class="btn btn-primary" data-invite-user>+ Convidar usuário</button>`:'')}<section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Usuário</th><th>E-mail</th><th>Perfil</th><th>Status</th></tr></thead><tbody>${d.team.map(u=>`<tr><td><strong>${esc(u.full_name||'Usuário')}</strong></td><td>${esc(u.email||'—')}</td><td>${badge(roleLabel(u.role),'blue')}</td><td>${u.active?badge('Ativo','green'):badge('Inativo')}</td></tr>`).join('')}</tbody></table></div></section>`,{})}

function settingsPage(d){const c=d.company,s=d.subscription||{};return shell(d,'configuracoes',`${pageHead('Configurações','Identidade visual, experiência de avaliação e detalhes do contrato.')}<div class="settings-grid"><div><section class="panel"><header class="panel-head"><div><h2>Estabelecimento</h2><p>Dados exibidos no painel e na tela pública</p></div></header><div class="panel-body"><form id="company-settings" class="form-grid"><div class="field full"><label>Nome</label><input name="name" value="${esc(c.name)}" required></div><div class="field"><label>Cor principal</label><input type="color" name="primary_color" value="${esc(c.primary_color||'#0A5CFF')}"></div><div class="field"><label>Slug</label><input value="${esc(c.slug)}" disabled></div><div class="field full"><label>Pergunta principal</label><input name="feedback_question" maxlength="160" value="${esc(c.feedback_question||'Como foi seu atendimento?')}"></div><div class="field full"><label>Subtítulo</label><input name="feedback_subtitle" maxlength="240" value="${esc(c.feedback_subtitle||'')}"></div><div class="field full"><label>Mensagem de agradecimento</label><input name="thank_you_message" maxlength="240" value="${esc(c.thank_you_message||'')}"></div><div class="field full">${d.currentUser?.role==='owner'?'<button class="btn btn-primary">Salvar configurações</button>':'<p class="form-hint">Somente o proprietário pode alterar estas configurações.</p>'}</div></form></div></section></div><aside class="plan-card"><small>PLANO ATUAL</small><h3>${esc(s.plan_name||c.plan_name||'Profissional')}</h3><div class="plan-price">${money(s.monthly_price??c.monthly_price)} <span>/ mês</span></div><p style="color:#a5b8d9;line-height:1.55;font-size:11px">Até ${s.point_limit??c.point_limit} pontos de avaliação, avaliações ilimitadas, dashboard, alertas e suporte.</p><div style="height:12px"></div><small>PRÓXIMO VENCIMENTO</small><b style="display:block;margin-top:5px">${dateOnly(s.next_due_date)}</b><div style="height:16px"></div>${statusBadge(s.status||c.status)}</aside></div>`,{})}

function adminDashboard(companies){const active=companies.filter(c=>c.status==='active'&&(!c.subscription_status||['active','trial'].includes(c.subscription_status))),mrr=active.reduce((s,c)=>s+Number(c.monthly_price||0),0),points=companies.reduce((s,c)=>s+Number(c.point_count||0),0);const d={company:{name:'TAJO Digital'}};return shell(d,'admin-dashboard',`${pageHead('Admin TAJO','Gestão da base de clientes e da receita recorrente.',`<button class="btn btn-primary" data-admin-new-company>+ Novo cliente</button>`)}<div class="admin-banner"><div><b>TAJO Avalie • SaaS recorrente</b><p>Implantação + mensalidade por estabelecimento, com isolamento multiempresa no Supabase.</p></div>${badge(`${companies.length} clientes`,'blue')}</div><div class="stats">${stat('Clientes',companies.length,'Empresas cadastradas','◆')}${stat('MRR',money(mrr),'Receita mensal ativa','R$','green')}${stat('Pontos ativos',points,'Caixas e setores','⌖')}${stat('Pendências',companies.filter(c=>['past_due','suspended'].includes(c.subscription_status)||c.status==='suspended').length,'Cobrança / acesso','!','red')}</div><section class="panel"><header class="panel-head"><div><h2>Clientes</h2><p>Visão consolidada da operação</p></div><button class="btn btn-outline btn-sm" data-admin-nav="admin-clientes">Ver todos</button></header>${adminCompanyTable(companies.slice(0,8))}</section>`,{admin:true})}
function adminCompanyTable(companies){return `<div class="table-wrap"><table class="table"><thead><tr><th>Empresa</th><th>Plano</th><th>Pontos</th><th>Mensalidade</th><th>Vencimento</th><th>Status</th></tr></thead><tbody>${companies.map(c=>`<tr><td><strong>${esc(c.name)}</strong><br><span class="muted">/${esc(c.slug)}</span></td><td>${badge(c.plan_name||'Profissional','blue')}</td><td>${c.point_count||0}/${c.point_limit||12}</td><td>${money(c.monthly_price||0)}</td><td>${dateOnly(c.next_due_date)}</td><td>${statusBadge(c.subscription_status||c.status)}</td></tr>`).join('')}</tbody></table></div>`}
function adminClients(companies){const d={company:{name:'TAJO Digital'}};return shell(d,'admin-clientes',`${pageHead('Clientes SaaS','Cadastre e acompanhe os estabelecimentos da plataforma.',`<button class="btn btn-primary" data-admin-new-company>+ Novo cliente</button>`)}<section class="panel">${adminCompanyTable(companies)}</section>`,{admin:true})}
function adminBilling(companies){const d={company:{name:'TAJO Digital'}},mrr=companies.filter(c=>c.subscription_status==='active'||(!c.subscription_status&&c.status==='active')).reduce((s,c)=>s+Number(c.monthly_price||0),0);return shell(d,'admin-faturamento',`${pageHead('Recorrência','Controle comercial da mensalidade do TAJO Avalie.')}<div class="stats">${stat('MRR',money(mrr),'Mensalidade ativa','R$','green')}${stat('Contratos ativos',companies.filter(c=>c.subscription_status==='active'||(!c.subscription_status&&c.status==='active')).length,'Clientes pagando','✓','green')}${stat('Em atraso',companies.filter(c=>c.subscription_status==='past_due').length,'Requer cobrança','!','red')}${stat('Ticket médio',money(companies.length?mrr/companies.length:0),'Por empresa','◆')}</div><section class="panel"><header class="panel-head"><div><h2>Próximos vencimentos</h2><p>Resumo dos contratos</p></div></header>${adminCompanyTable([...companies].sort((a,b)=>String(a.next_due_date||'9999').localeCompare(String(b.next_due_date||'9999'))))}</section>`,{admin:true})}

let renderVersion=0
async function render({silent=false}={}){
  const version=++renderVersion
  const r=route(),parts=pathParts(); if(!silent)app.innerHTML='<div class="boot"><img src="/schwambach-logo.png"><span>Carregando…</span></div>'
  try{
    if(r==='/'){app.innerHTML=landing();bind();return}
    if(r==='/nova-senha'){app.innerHTML=passwordPage();bind();return}
    if(r==='/admin/login'){app.innerHTML=loginPage(true);bind();return}
    if(r==='/admin'||r==='/admin/clientes'||r==='/admin/faturamento'){
      if(!isAdminSession()){go('/admin/login');return}
      const companies=await api.adminCompanies();if(version!==renderVersion)return;state.adminCompanies=companies
      app.innerHTML=r==='/admin/clientes'?adminClients(companies):r==='/admin/faturamento'?adminBilling(companies):adminDashboard(companies);bind();return
    }
    const tenant=parts[0]
    if(parts[1]==='painel'){
      if(parts[2]==='login'){app.innerHTML=loginPage(false,tenant);bind();return}
      const s=api.uiSession();if(!s||s.isPlatformAdmin){go(`/${tenant}/painel/login`);return}
      if(!isDemoMode()&&s.companySlug&&s.companySlug!==tenant){go(`/${s.companySlug}/painel`);return}
      const d=await api.companyData();if(version!==renderVersion)return;d.currentUser=s.profile?{...s.profile,role:s.role}:{full_name:s.email?.split('@')[0],role:s.role}
      const page=parts[2]||'dashboard'; const f={dashboard:dashboardPage,'avaliacoes':evaluationsPage,'pontos':pointsPage,'funcionarios':employeesPage,'turnos':shiftsPage,'ocorrencias':incidentsPage,'ranking':rankingPage,'relatorios':reportsPage,'qrcodes':qrPage,'equipe':teamPage,'configuracoes':settingsPage}[page]||dashboardPage
      app.innerHTML=f(d);bind(d);return
    }
    const pointSlug=parts[1]||APP_CONFIG.defaultPointSlug;const html=await publicPage(tenant,pointSlug);if(version!==renderVersion)return;app.innerHTML=html;bind();return
  }catch(err){console.error(err);app.innerHTML=`<div class="public-page"><div class="public-card"><div class="public-body">${empty('Não foi possível carregar o sistema',err.message||'Erro inesperado.') }<div style="height:14px"></div><button class="btn btn-primary btn-block" data-retry>Tentar novamente</button></div></div></div>`;bind()}
}

function bind(d=null){
  $$('[data-link]').forEach(a=>a.addEventListener('click',e=>{if(a.target==='_blank')return;e.preventDefault();go(new URL(a.href,location.href).pathname)}))
  $$('[data-nav]').forEach(b=>b.addEventListener('click',()=>{const slug=(d?.company?.slug||api.uiSession()?.companySlug||APP_CONFIG.defaultTenantSlug);go(`/${slug}/painel/${b.dataset.nav==='dashboard'?'':b.dataset.nav}`)}))
  $$('[data-admin-nav]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.adminNav==='admin-dashboard'?'/admin':b.dataset.adminNav==='admin-clientes'?'/admin/clientes':'/admin/faturamento')))
  $$('[data-logout]').forEach(b=>b.addEventListener('click',async()=>{const admin=isAdminSession();await api.signOut();go(admin?'/admin/login':`/${d?.company?.slug||APP_CONFIG.defaultTenantSlug}/painel/login`)}))
  $$('[data-refresh]').forEach(b=>b.addEventListener('click',async()=>{try{if(!isDemoMode()&&!isAdminSession())await api.refresh();await render({silent:true});toast('Dados atualizados.')}catch(e){toast(e.message,'error')}}))
  $$('[data-help]').forEach(b=>b.addEventListener('click',()=>openModal('Ajuda',`<p style="line-height:1.7;color:#64748b">TAJO Avalie centraliza avaliações, pontos, funcionários, turnos, ocorrências e relatórios. Para suporte comercial ou técnico, entre em contato com <b>${esc(APP_CONFIG.supportEmail)}</b>.</p>`,`<button class="btn btn-primary" data-close-modal>Fechar</button>`)))
  $('[data-retry]')?.addEventListener('click',()=>render())
  $('[data-print-page]')?.addEventListener('click',()=>window.print())

  $('#login-form')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),btn=e.currentTarget.querySelector('button[type=submit]'),admin=e.currentTarget.dataset.admin==='true';btn.disabled=true;btn.textContent='Entrando…';try{const tenant=pathParts()[0];const s=await api.signIn(fd.get('email'),fd.get('password'),{admin,tenantSlug:admin?null:tenant});go(admin?'/admin':`/${s.companySlug||tenant}/painel`)}catch(err){toast(err.message,'error');btn.disabled=false;btn.textContent='Entrar no painel'}})
  $('[data-recover]')?.addEventListener('click',async()=>{const email=$('#login-form input[name=email]')?.value;if(!email){toast('Digite seu e-mail primeiro.','error');return}try{await api.recover(email);toast(isDemoMode()?'No modo demonstração o e-mail não é enviado.':'E-mail de recuperação enviado.')}catch(err){toast(err.message,'error')}})
  $('#password-form')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);if(fd.get('password')!==fd.get('confirm')){toast('As senhas não coincidem.','error');return}try{await supabase.updatePassword(fd.get('password'));toast('Senha atualizada.');setTimeout(()=>go(`/${APP_CONFIG.defaultTenantSlug}/painel/login`),900)}catch(err){toast(err.message,'error')}})

  $$('[data-rating]').forEach(b=>b.addEventListener('click',()=>{state.public.rating=Number(b.dataset.rating);state.public.step=2;render()}))
  $$('[data-reason]').forEach(b=>b.addEventListener('click',()=>{const v=b.dataset.reason;state.public.reasons=state.public.reasons.includes(v)?state.public.reasons.filter(x=>x!==v):[...state.public.reasons,v];render()}))
  $('[data-public-next]')?.addEventListener('click',()=>{state.public.step=3;render()})
  $('[data-public-back]')?.addEventListener('click',()=>{if(state.public.step===3)state.public.comment=$('#public-comment')?.value||'';state.public.step=Math.max(1,state.public.step-1);render()})
  $('[data-submit-feedback]')?.addEventListener('click',async()=>{if(!state.public.rating){toast('Selecione uma nota.','error');return}const parts=pathParts(),btn=$('[data-submit-feedback]');btn.disabled=true;btn.textContent='Enviando…';try{state.public.comment=$('#public-comment')?.value||'';await api.submitFeedback({companySlug:parts[0],pointSlug:parts[1],rating:state.public.rating,reasons:state.public.reasons,comment:state.public.comment});state.public.step=4;render()}catch(err){toast(err.message==='RATE_LIMITED'?'Você já enviou uma avaliação recentemente neste ponto.':err.message,'error');btn.disabled=false;btn.textContent='Enviar avaliação'}})
  $('[data-public-reset]')?.addEventListener('click',()=>{state.public.step=1;state.public.rating=null;state.public.reasons=[];state.public.comment='';render()})

  $('[data-new-point]')?.addEventListener('click',()=>{if(d && d.points.filter(p=>p.active).length >= (d.subscription?.point_limit||d.company.point_limit||12)){openModal('Limite de pontos atingido',`<p class="muted">Todos os pontos previstos no plano estão ativos. Desative um ponto que não é usado ou solicite a ampliação do limite antes de cadastrar outro.</p>`,`<button class="btn btn-primary" data-close-modal>Entendi</button>`);return}openModal('Novo ponto de avaliação',`<form id="point-form" class="form-grid"><div class="field full"><label>Nome</label><input name="name" placeholder="Ex.: Caixa 07" required></div><div class="field"><label>Tipo</label><select name="type"><option>Caixa</option><option>Açougue</option><option>Padaria</option><option>Hortifruti</option><option>Atendimento</option><option>Delivery</option><option>Outro</option></select></div><div class="field"><label>Slug do link</label><input name="slug" placeholder="Gerado automaticamente"></div></form>`,`<button class="btn btn-outline" data-close-modal>Cancelar</button><button class="btn btn-primary" data-save-point>Criar ponto</button>`)});

  $('[data-new-employee]')?.addEventListener('click',()=>openModal('Novo funcionário',`<form id="employee-form" class="form-grid"><div class="field full"><label>Nome completo</label><input name="name" required></div><div class="field"><label>Código interno</label><input name="code"></div><div class="field"><label>Cargo</label><input name="role" value="Operador(a) de caixa"></div></form>`,`<button class="btn btn-outline" data-close-modal>Cancelar</button><button class="btn btn-primary" data-save-employee>Cadastrar</button>`));

  $$('[data-edit-point]').forEach(b=>b.addEventListener('click',()=>{
    const p=point(d,b.dataset.editPoint)
    openModal(`Editar ${p.name}`,`<form id="edit-point-form" class="form-grid"><div class="field full"><label>Nome exibido</label><input name="name" required minlength="2" maxlength="100" value="${esc(p.name)}"></div><div class="field"><label>Tipo de ponto</label><input name="point_type" required maxlength="60" value="${esc(p.point_type)}"></div><div class="field"><label>Link permanente</label><input readonly value="${esc(publicUrl(d.company.slug,p.slug))}"></div><label class="toggle-field full"><input name="active" type="checkbox" ${p.active?'checked':''}><span>Ativo para novas avaliações</span></label><p class="form-hint full">O endereço e o QR Code não mudam ao editar o nome.</p></form>`,`<button class="btn btn-outline" data-close-modal>Cancelar</button><button class="btn btn-primary" data-save-edit-point="${p.id}">Salvar alterações</button>`,true)
  }))
  $$('[data-edit-employee]').forEach(b=>b.addEventListener('click',()=>{
    const e=d.employees.find(x=>x.id===b.dataset.editEmployee)
    openModal(`Editar funcionário`, `<form id="edit-employee-form" class="form-grid"><div class="field full"><label>Nome completo</label><input name="name" required minlength="2" maxlength="120" value="${esc(e.name)}"></div><div class="field"><label>Código interno</label><input name="employee_code" value="${esc(e.employee_code||'')}"></div><div class="field"><label>Função</label><input name="role_name" value="${esc(e.role_name||'')}"></div><label class="toggle-field full"><input name="active" type="checkbox" ${e.active?'checked':''}><span>Funcionário ativo</span></label></form>`,`<button class="btn btn-outline" data-close-modal>Cancelar</button><button class="btn btn-primary" data-save-edit-employee="${e.id}">Salvar alterações</button>`,true)
  }))
  $('[data-new-shift]')?.addEventListener('click',()=>{if(!d)return;openModal('Iniciar turno',`<form id="shift-form" class="form-grid"><div class="field"><label>Ponto</label><select name="point">${d.points.filter(p=>p.active).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Funcionário</label><select name="employee">${d.employees.filter(e=>e.active).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></div></form>`,`<button class="btn btn-outline" data-close-modal>Cancelar</button><button class="btn btn-primary" data-start-shift>Iniciar</button>`)});
  $$('[data-end-shift]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Encerrar este turno?'))return;try{await api.endShift(b.dataset.endShift);toast('Turno encerrado.');render()}catch(err){toast(err.message,'error')}}))

  $$('[data-point-detail]').forEach(b=>b.addEventListener('click',()=>{const p=point(d,b.dataset.pointDetail),m=pointMetric(d,p),u=publicUrl(d.company.slug,p.slug);openModal(p.name,`<div class="card-kv"><div class="kv"><span>Tipo</span><b>${esc(p.point_type)}</b></div><div class="kv"><span>Nota</span><b>${m.score?m.score.toFixed(2):'—'}</b></div><div class="kv"><span>Avaliações</span><b>${m.reviews}</b></div><div class="kv"><span>Turno</span><b>${esc(p.employee_name||'Sem funcionário')}</b></div></div><div class="field"><label>Link permanente</label><input value="${esc(u)}" readonly></div>`,`<button class="btn btn-outline" data-copy="${esc(u)}">Copiar link</button><button class="btn btn-primary" data-close-modal>Fechar</button>`)}))
  $$('[data-point-qr]').forEach(b=>b.addEventListener('click',()=>{const p=point(d,b.dataset.pointQr),u=publicUrl(d.company.slug,p.slug),known=/^caixa-(0[1-9]|1[0-2])$/.test(p.slug),qr=known?`/qrcodes/${p.slug}.svg`:`https://quickchart.io/qr?text=${encodeURIComponent(u)}&size=320&margin=4`;openModal(`QR Code • ${p.name}`,`<div class="qr-box"><img src="${qr}" alt="QR Code de ${esc(p.name)}"></div><div class="field"><label>Link oficial</label><input value="${esc(u)}" readonly></div><p class="muted" style="font-size:12px">O link é permanente e identifica o caixa, independentemente do funcionário em atendimento.</p>`,`<button class="btn btn-outline" data-copy="${esc(u)}">Copiar link</button>${known?`<a class="btn btn-outline" href="/placas/${p.slug}.html" target="_blank">Imprimir placa</a><a class="btn btn-primary" href="/qrcodes/${p.slug}.svg" download="schwambach-${p.slug}.svg">Baixar SVG</a>`:`<a class="btn btn-primary" href="${qr}" target="_blank" rel="noopener">Abrir QR</a>`}`)}))

  $$('[data-feedback-detail]').forEach(b=>b.addEventListener('click',()=>{const f=d.feedbacks.find(x=>x.id===b.dataset.feedbackDetail);openModal(`Avaliação ${String(f.id).slice(0,8)}`,`<div class="stats" style="grid-template-columns:repeat(3,1fr)">${stat('Nota',`${f.rating}/5`,ratingLabel(f.rating),ratingEmoji(f.rating),f.rating<=2?'red':'green')}${stat('Ponto',esc(f.point_name||'—'),'Origem','⌖')}${stat('Funcionário',esc(f.employee_name||'—'),'Turno vinculado','◎')}</div><div class="field"><label>Comentário</label><textarea readonly>${esc(f.comment||'Sem comentário.')}</textarea></div><div class="field"><label>Status</label><select id="feedback-status-modal"><option value="new" ${f.status==='new'?'selected':''}>Nova</option><option value="analyzing" ${f.status==='analyzing'?'selected':''}>Em análise</option><option value="resolved" ${f.status==='resolved'?'selected':''}>Resolvida</option><option value="archived" ${f.status==='archived'?'selected':''}>Arquivada</option></select></div>`,`<button class="btn btn-outline" data-close-modal>Cancelar</button><button class="btn btn-primary" data-save-feedback="${f.id}">Salvar</button>`,true)}))

  $$('[data-open-incident]').forEach(b=>b.addEventListener('click',()=>{const i=d.incidents.find(x=>x.id===b.dataset.openIncident);openModal(`Ocorrência ${String(i.id).slice(0,8)}`,`<div class="tags">${statusBadge(i.status)}${badge(i.severity==='critical'?'Crítica':i.severity==='warning'?'Atenção':'Informativa',i.severity==='critical'?'red':i.severity==='warning'?'amber':'blue')}</div><h3>${esc(i.title)}</h3><p class="muted" style="line-height:1.7">${esc(i.description||'')}</p><div class="field"><label>Status</label><select id="incident-status-modal"><option value="new" ${i.status==='new'?'selected':''}>Nova</option><option value="analyzing" ${i.status==='analyzing'?'selected':''}>Em análise</option><option value="resolved" ${i.status==='resolved'?'selected':''}>Resolvida</option><option value="archived" ${i.status==='archived'?'selected':''}>Arquivada</option></select></div>`,`<button class="btn btn-outline" data-close-modal>Cancelar</button><button class="btn btn-primary" data-save-incident="${i.id}">Salvar</button>`)}))

  $('[data-export-feedback]')?.addEventListener('click',async e=>{const btn=e.currentTarget;btn.disabled=true;const old=btn.textContent;btn.textContent='Exportando…';try{const all=await api.exportAllFeedbacks();const rows=['id,ponto,funcionario,nota,motivos,comentario,status,data',...all.map(f=>[f.id,f.point_name,f.employee_name,f.rating,(f.reason_codes||[]).join('|'),f.comment,f.status,f.created_at].map(csvEscape).join(','))];download('schwambach-avaliacoes.csv','\uFEFF'+rows.join('\n'),'text/csv;charset=utf-8');toast(`Exportação gerada: ${all.length} avaliações.`)}catch(err){toast(err.message,'error')}finally{btn.disabled=false;btn.textContent=old}})
  function filterFeedback(){const q=($('#feedback-search')?.value||'').toLowerCase(),rating=$('#feedback-rating')?.value,status=$('#feedback-status')?.value;$$('[data-feedback-card]').forEach(c=>{const okQ=!q||c.textContent.toLowerCase().includes(q),okR=!rating||c.dataset.rating===rating,okS=!status||c.dataset.status===status;c.style.display=okQ&&okR&&okS?'':'none'})}
  $('#feedback-search')?.addEventListener('input',filterFeedback);$('#feedback-rating')?.addEventListener('change',filterFeedback);$('#feedback-status')?.addEventListener('change',filterFeedback)

  $('[data-invite-user]')?.addEventListener('click',()=>openModal('Convidar usuário',`<form id="invite-form" class="form-grid"><div class="field full"><label>Nome</label><input name="full_name" required></div><div class="field"><label>E-mail</label><input name="email" type="email" required></div><div class="field"><label>Perfil</label><select name="role"><option value="manager">Gerente</option><option value="owner">Proprietário</option></select></div></form><div class="demo-note">No Supabase real, o usuário receberá um convite por e-mail para definir a senha.</div>`,`<button class="btn btn-outline" data-close-modal>Cancelar</button><button class="btn btn-primary" data-send-invite>Enviar convite</button>`));

  $('#company-settings')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await api.updateCompany({name:fd.get('name'),primary_color:fd.get('primary_color'),feedback_question:fd.get('feedback_question'),feedback_subtitle:fd.get('feedback_subtitle'),thank_you_message:fd.get('thank_you_message')});toast('Configurações salvas.');render()}catch(err){toast(err.message,'error')}})

  $('[data-admin-new-company]')?.addEventListener('click',()=>openModal('Novo cliente SaaS',`<form id="admin-company-form" class="form-grid"><div class="field full"><label>Empresa</label><input name="name" required></div><div class="field"><label>Slug</label><input name="slug" placeholder="Gerado automaticamente"></div><div class="field"><label>Responsável</label><input name="responsible"></div><div class="field full"><label>E-mail do responsável</label><input name="email" type="email"></div><div class="field"><label>Implantação</label><input name="setup" type="number" value="390"></div><div class="field"><label>Mensalidade</label><input name="monthly" type="number" value="390"></div><div class="field"><label>Limite de pontos</label><input name="limit" type="number" value="12"></div><div class="field"><label>Dia de vencimento</label><input name="billing_day" type="number" min="1" max="28" value="15"></div></form>`,`<button class="btn btn-outline" data-close-modal>Cancelar</button><button class="btn btn-primary" data-save-company>Criar cliente</button>`,true));
}


document.addEventListener('click', async (e)=>{
  const copyBtn=e.target.closest('[data-copy]'); if(copyBtn){await copy(copyBtn.dataset.copy); return}
  const pointBtn=e.target.closest('[data-save-point]')
  if(pointBtn){const f=$('#point-form');if(!f?.reportValidity())return;const fd=new FormData(f),name=fd.get('name');if(!name)return;try{pointBtn.disabled=true;await api.createPoint({name,type:fd.get('type'),slug:fd.get('slug')||slugify(name)});$('.modal-back')?.remove();toast('Ponto criado.');render()}catch(err){toast(err.message,'error');pointBtn.disabled=false}return}
  const empBtn=e.target.closest('[data-save-employee]')
  if(empBtn){const f=$('#employee-form');if(!f?.reportValidity())return;const fd=new FormData(f);try{empBtn.disabled=true;await api.createEmployee({name:fd.get('name'),code:fd.get('code'),role:fd.get('role')});$('.modal-back')?.remove();toast('Funcionário cadastrado.');render()}catch(err){toast(err.message,'error');empBtn.disabled=false}return}
  const editPointBtn=e.target.closest('[data-save-edit-point]')
  if(editPointBtn){const f=$('#edit-point-form');if(!f?.reportValidity())return;const fd=new FormData(f)
    if(!fd.has('active')){const current=await api.companyData();if(current.shifts.some(t=>t.status==='active'&&t.point_id===editPointBtn.dataset.saveEditPoint)){toast('Encerre primeiro o turno ativo deste caixa.','error');return}}
    try{editPointBtn.disabled=true;await api.updatePoint(editPointBtn.dataset.saveEditPoint,{name:String(fd.get('name')).trim(),point_type:String(fd.get('point_type')).trim(),active:fd.has('active')});$('.modal-back')?.remove();toast('Ponto atualizado.');await render({silent:true})}catch(err){toast(err.message,'error');editPointBtn.disabled=false}return}
  const editEmployeeBtn=e.target.closest('[data-save-edit-employee]')
  if(editEmployeeBtn){const f=$('#edit-employee-form');if(!f?.reportValidity())return;const fd=new FormData(f)
    const active=fd.has('active'), current=await api.companyData();if(!active && current.shifts.some(s=>s.status==='active'&&s.employee_id===editEmployeeBtn.dataset.saveEditEmployee)){toast('Encerre primeiro o turno ativo deste funcionário.','error');return}
    try{editEmployeeBtn.disabled=true;await api.updateEmployee(editEmployeeBtn.dataset.saveEditEmployee,{name:String(fd.get('name')).trim(),employee_code:String(fd.get('employee_code')||'').trim()||null,role_name:String(fd.get('role_name')||'').trim()||null,active});$('.modal-back')?.remove();toast('Funcionário atualizado.');await render({silent:true})}catch(err){toast(err.message,'error');editEmployeeBtn.disabled=false}return}
  const shiftBtn=e.target.closest('[data-start-shift]')
  if(shiftBtn){const f=$('#shift-form');if(!f)return;const fd=new FormData(f);try{shiftBtn.disabled=true;await api.startShift(fd.get('point'),fd.get('employee'));$('.modal-back')?.remove();toast('Turno iniciado.');render()}catch(err){toast(err.message,'error');shiftBtn.disabled=false}return}
  const fbBtn=e.target.closest('[data-save-feedback]')
  if(fbBtn){try{fbBtn.disabled=true;await api.setFeedbackStatus(fbBtn.dataset.saveFeedback,$('#feedback-status-modal').value);$('.modal-back')?.remove();toast('Avaliação atualizada.');render()}catch(err){toast(err.message,'error');fbBtn.disabled=false}return}
  const incBtn=e.target.closest('[data-save-incident]')
  if(incBtn){try{incBtn.disabled=true;await api.setIncidentStatus(incBtn.dataset.saveIncident,$('#incident-status-modal').value);$('.modal-back')?.remove();toast('Ocorrência atualizada.');render()}catch(err){toast(err.message,'error');incBtn.disabled=false}return}
  const inviteBtn=e.target.closest('[data-send-invite]')
  if(inviteBtn){const f=$('#invite-form');if(!f?.reportValidity())return;const fd=new FormData(f);try{inviteBtn.disabled=true;await api.inviteUser({fullName:fd.get('full_name'),email:fd.get('email'),role:fd.get('role')});$('.modal-back')?.remove();toast('Convite processado.');render()}catch(err){toast(err.message,'error');inviteBtn.disabled=false}return}
  const companyBtn=e.target.closest('[data-save-company]')
  if(companyBtn){const f=$('#admin-company-form');if(!f?.reportValidity())return;const fd=new FormData(f),name=fd.get('name');try{companyBtn.disabled=true;await api.adminCreateCompany({name,slug:fd.get('slug')||slugify(name),responsible:fd.get('responsible'),email:fd.get('email'),setup_price:Number(fd.get('setup')),monthly_price:Number(fd.get('monthly')),point_limit:Number(fd.get('limit')),billing_day:Number(fd.get('billing_day'))});$('.modal-back')?.remove();toast('Cliente criado.');state.adminCompanies=null;render()}catch(err){toast(err.message,'error');companyBtn.disabled=false}return}
})

let autoRefreshRunning=false,lastAutoRefresh=0
async function backgroundRefresh(){
  if(autoRefreshRunning||document.hidden||!location.pathname.includes('/painel')||location.pathname.endsWith('/login')||isDemoMode()||!api.uiSession()||Date.now()-lastAutoRefresh<22000)return
  lastAutoRefresh=Date.now();autoRefreshRunning=true
  try{await api.refresh();if(location.pathname.includes('/painel')&&!document.hidden)await render({silent:true})}
  catch(err){console.warn('Atualização automática não concluída:',err.message)}
  finally{autoRefreshRunning=false}
}
setInterval(backgroundRefresh,30000)
document.addEventListener('visibilitychange',()=>{if(!document.hidden)backgroundRefresh()})
window.addEventListener('focus',backgroundRefresh)
window.addEventListener('popstate',()=>render())
render()
